const JR_AREA_VERIFY_URL = 'https://sesau-certo.vercel.app/api/verify-area-ticket';
const JR_HEALTH_AREAS = new Set([
  'radiologia','enfermagem','tecnico','fisioterapia','farmaceutico','laboratorio',
  'nutricao','biomedicina','odontologia','psicologia','acsfiscal','endemias','clinico'
]);

function jrReadCookies(req){
  const raw = String(req && req.headers && req.headers.cookie || '');
  const out = {};
  raw.split(';').forEach(function(part){
    const i = part.indexOf('=');
    if(i < 0) return;
    const key = part.slice(0,i).trim();
    if(!key) return;
    try{ out[key] = decodeURIComponent(part.slice(i+1).trim()); }
    catch(e){ out[key] = part.slice(i+1).trim(); }
  });
  return out;
}

async function jrVerifyAreaTicket(ticket){
  if(!ticket || String(ticket).length > 8192) return '';
  const controller = new AbortController();
  const timer = setTimeout(function(){ controller.abort(); }, 7000);
  try{
    const response = await fetch(JR_AREA_VERIFY_URL,{
      method:'POST',
      cache:'no-store',
      signal:controller.signal,
      headers:{'Content-Type':'application/json','Accept':'application/json'},
      body:JSON.stringify({ticket:String(ticket)})
    });
    const data = await response.json().catch(function(){ return null; });
    const area = String(data && data.area || '').trim().toLowerCase();
    return response.ok && data && data.ok && JR_HEALTH_AREAS.has(area) ? area : '';
  }catch(e){
    return '';
  }finally{
    clearTimeout(timer);
  }
}

async function jrPurchasedAreasFromRequest(req){
  const cookies = jrReadCookies(req);
  const tickets = Object.keys(cookies)
    .filter(function(key){ return key.indexOf('jr_area_access_') === 0; })
    .map(function(key){ return cookies[key]; })
    .filter(Boolean)
    .slice(0,20);
  if(!tickets.length) return [];
  const verified = await Promise.all(tickets.map(jrVerifyAreaTicket));
  return Array.from(new Set(verified.filter(Boolean)));
}

